import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
// Max reduction over dim=1 of a contiguous (B, D1, D2) float32 tensor.
// Optimization: each thread reduces two output columns, j and j + blockDim.x,
// so every warp still issues fully coalesced 32-lane column loads while each
// thread carries 8 independent accumulators. This doubles per-thread memory-
// level parallelism and halves the number of blocks/threads without adding
// redundant global reads for this bandwidth-bound streaming reduction.
__global__ void max_reduce_dim1_kernel(const float* __restrict__ x,
                                       float* __restrict__ out,
                                       int D1, int D2) {
    const int b = blockIdx.y;
    const int tx = threadIdx.x;
    const int s = threadIdx.y;
    const int split = blockDim.y;
    const int j0 = blockIdx.x * (blockDim.x * 2) + tx;
    const int j1 = j0 + blockDim.x;
    __shared__ float smem0[4][64];
    __shared__ float smem1[4][64];
    float a0 = -INFINITY;
    float a1 = -INFINITY;
    float a2 = -INFINITY;
    float a3 = -INFINITY;
    float b0 = -INFINITY;
    float b1 = -INFINITY;
    float b2 = -INFINITY;
    float b3 = -INFINITY;
    if (j0 < D2) {
        const bool has1 = j1 < D2;
        const float* base = x + (size_t)b * D1 * D2 + (size_t)s * D2;
        const float* q0 = base + j0;
        const float* q1 = has1 ? base + j1 : nullptr;
        const size_t stride = (size_t)split * D2;
        int i = s;
        for (; i + 3 * split < D1; i += 4 * split) {
            a0 = fmaxf(a0, __ldg(q0));
            a1 = fmaxf(a1, __ldg(q0 + stride));
            a2 = fmaxf(a2, __ldg(q0 + 2 * stride));
            a3 = fmaxf(a3, __ldg(q0 + 3 * stride));
            if (has1) {
                b0 = fmaxf(b0, __ldg(q1));
                b1 = fmaxf(b1, __ldg(q1 + stride));
                b2 = fmaxf(b2, __ldg(q1 + 2 * stride));
                b3 = fmaxf(b3, __ldg(q1 + 3 * stride));
                q1 += 4 * stride;
            }
            q0 += 4 * stride;
        }
        for (; i < D1; i += split) {
            a0 = fmaxf(a0, __ldg(q0));
            if (has1) {
                b0 = fmaxf(b0, __ldg(q1));
                q1 += stride;
            }
            q0 += stride;
        }
    }
    float m0 = fmaxf(fmaxf(a0, a1), fmaxf(a2, a3));
    float m1 = fmaxf(fmaxf(b0, b1), fmaxf(b2, b3));
    smem0[s][tx] = m0;
    smem1[s][tx] = m1;
    __syncthreads();
    if (s == 0) {
        if (j0 < D2) {
            #pragma unroll
            for (int k = 1; k < 4; ++k) m0 = fmaxf(m0, smem0[k][tx]);
            out[(size_t)b * D2 + j0] = m0;
        }
        if (j1 < D2) {
            #pragma unroll
            for (int k = 1; k < 4; ++k) m1 = fmaxf(m1, smem1[k][tx]);
            out[(size_t)b * D2 + j1] = m1;
        }
    }
}
torch::Tensor max_reduce_dim1(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "input must be CUDA");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(x.dim() == 3, "input must be 3D");
    auto xc = x.contiguous();
    const int B  = (int)xc.size(0);
    const int D1 = (int)xc.size(1);
    const int D2 = (int)xc.size(2);
    auto out = torch::empty({B, D2}, xc.options());
    dim3 block(64, 4);
    const int cols_per_block = (int)block.x * 2;
    dim3 grid((D2 + cols_per_block - 1) / cols_per_block, B);
    max_reduce_dim1_kernel<<<grid, block, 0, at::cuda::getCurrentCUDAStream()>>>(
        xc.data_ptr<float>(), out.data_ptr<float>(), D1, D2);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}
"""
cpp_src = "torch::Tensor max_reduce_dim1(torch::Tensor x);"
_mod = load_inline(
    name="max_reduce_dim1_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["max_reduce_dim1"],
    verbose=False,
)
class ModelNew(nn.Module):
    """
    Model that performs Max reduction over a specific dimension using a
    custom CUDA kernel (specialized for reduction over dim=1 of a 3D tensor).
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        dim = self.dim if self.dim >= 0 else self.dim + x.dim()
        if x.is_cuda and x.dim() == 3 and dim == 1 and x.dtype == torch.float32:
            return _mod.max_reduce_dim1(x)
        return torch.max(x, dim=self.dim)[0]

